      .DEPTH_LOG2(DEPTH_LOG2),
      .NUM_CMP   (NUM_CMP),
      .SEQ_STAGES(SEQ_STAGES),
      .RLE_EN    (RLE_EN),
      .TS_W      (TS_W)
  ) u_csr (
      .clk          (clk),
      .rst          (rst),
      .csr_addr     (dut_addr),
      .csr_wdata    (dut_wdata),
      .csr_write    (dut_write),
      .csr_read     (csr_read),
      .csr_rdata    (csr_rdata),
      .arm          (arm),
      .disarm       (disarm),
      .force_trig   (force_trig),
      .pretrig      (pretrig),
      .windows      (windows),
      .rle_enable   (rle_enable),
      /* verilator lint_off PINCONNECTEMPTY */  // SMPL_CTRL outputs (#17/#20) unused in this TB
      .decim        (),
      .qual_en      (),
      .qual_sel     (),
      /* verilator lint_on PINCONNECTEMPTY */
      .state        (state),
      .triggered    (triggered),
      .wrapped      (wrapped),
      .windows_done (windows_done),
      .trig_index   (trig_index),
      .ts           (ts),
      .ts_at_trig   (ts_at_trig),
      .buf_rd_addr  (buf_rd_addr),
      .buf_rd_data  (buf_rd_data),
      .win_rd_addr  (win_rd_addr),
      .win_rd_data  (win_rd_data),
      .cmp_mask     (cmp_mask),
      .cmp_value    (cmp_value),
      .cmp_edge_mask(cmp_edge_mask),
      .cmp_edge_pol (cmp_edge_pol),
